import { test, expect } from '@playwright/test';

test.describe('Mark Record as Favourite', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/records');
    await page.waitForLoadState('networkidle');
  });

  test('should mark a record as favourite by clicking the favourite button', async ({ page }) => {
    const recordRow = page.getByRole('row').filter({ hasText: 'Test Record' }).first();
    const favouriteButton = recordRow.getByRole('button', { name: /favourite|star|heart/i });

    await expect(favouriteButton).toBeVisible();
    const initialState = await favouriteButton.getAttribute('aria-pressed');

    await favouriteButton.click();

    const updatedState = await favouriteButton.getAttribute('aria-pressed');
    expect(updatedState).not.toBe(initialState);
    await expect(favouriteButton).toHaveAttribute('aria-pressed', 'true');
  });

  test('should display favourite indicator on marked record', async ({ page }) => {
    const recordRow = page.getByRole('row').filter({ hasText: 'Test Record' }).first();
    const favouriteButton = recordRow.getByRole('button', { name: /favourite|star|heart/i });

    await favouriteButton.click();

    const favouriteIcon = recordRow.getByRole('img', { name: /favourite|starred/i });
    await expect(favouriteIcon).toBeVisible();
  });

  test('should unmark a record from favourite', async ({ page }) => {
    const recordRow = page.getByRole('row').filter({ hasText: 'Favourite Record' }).first();
    const favouriteButton = recordRow.getByRole('button', { name: /favourite|star|heart/i });

    await expect(favouriteButton).toHaveAttribute('aria-pressed', 'true');

    await favouriteButton.click();

    await expect(favouriteButton).toHaveAttribute('aria-pressed', 'false');
  });

  test('should persist favourite status after page reload', async ({ page }) => {
    const recordRow = page.getByRole('row').filter({ hasText: 'Test Record' }).first();
    const favouriteButton = recordRow.getByRole('button', { name: /favourite|star|heart/i });

    await favouriteButton.click();
    await expect(favouriteButton).toHaveAttribute('aria-pressed', 'true');

    await page.reload();
    await page.waitForLoadState('networkidle');

    const reloadedRecordRow = page.getByRole('row').filter({ hasText: 'Test Record' }).first();
    const reloadedFavouriteButton = reloadedRecordRow.getByRole('button', { name: /favourite|star|heart/i });

    await expect(reloadedFavouriteButton).toHaveAttribute('aria-pressed', 'true');
  });
});
